def record_usage(state, key, model, tokens) do
  if not (is_number(tokens) and tokens >= 0), do: raise("tokens must be a non-negative number")
  usage = Map.get(state, "usage", %{})
  entry = Map.get(usage, key, %{"total" => 0, "models" => %{}, "calls" => 0})
  total = entry["total"] + tokens
  models = Map.update(entry["models"], model, tokens, fn t -> t + tokens end)
  new_entry = %{"total" => total, "models" => models, "calls" => entry["calls"] + 1}
  {total, Map.put(state, "usage", Map.put(usage, key, new_entry))}
end

